import ast,hashlib,json,os,subprocess
from pathlib import Path
root=Path.cwd(); compiler=root/'build/native/native/kalandra'; old=root/'build/native/native/ordinary-buffer-faults'; out=root/'benchmarks/.build/buffer-direct-2026-10-27/qualification/cli';out.mkdir(exist_ok=True)
suite=root/'native/tests/OrdinaryBufferFaultTests.py';tree=ast.parse(suite.read_text());fixtures=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='fixtures' for t in n.targets))
inputs={'index':(17,2),'map':(17,0),'replay':(17,2),'nan':(0,0),'bool':(1,1),'minimum':(-2**63,0)}
rows=[];commands=[];files={}
for mode,flags in [('debug',[]),('optimized',['-O2']),('sanitized',['-O2','--sanitize']),('thread-sanitized',['-O2','--thread-sanitize'])]:
 for name,(lang,_,_,body) in fixtures.items():
  x,y=inputs[name];src=out/(mode+'-'+name+'.k');exe=src.with_suffix('');ir=src.with_suffix('.ll');text=f'fn value(seed:int64,index:int64)->{lang}:\n{body}\nfn main()->{lang}:\n  value({x},{y})\n';src.write_text(text)
  cmd=[str(compiler),str(src),'--emit-llvm',str(ir),'-o',str(exe),*flags];commands.append(cmd);r=subprocess.run(cmd,capture_output=True,text=True);assert r.returncode==0,(cmd,r.stderr)
  reference=old/(mode+'-'+name+'-recoverable');assert reference.exists()
  for fail in [0,1]:
   env=dict(os.environ,KALANDRA_TEST_REPORT_CLEANUP='1',KALANDRA_TEST_FAIL_ALLOC_AT=str(fail));actual=subprocess.run([exe],env=env,capture_output=True,text=True);expected=subprocess.run([str(reference),str(x),str(y)],env=env,capture_output=True,text=True)
   assert (actual.returncode,actual.stdout,actual.stderr)==(expected.returncode,expected.stdout,expected.stderr),(mode,name,fail,actual.stderr,expected.stderr)
   rows.append(dict(mode=mode,fixture=name,args=[x,y],allocation_failure=fail,status=actual.returncode,stdout=actual.stdout,stderr=actual.stderr,source=text))
  for f in [src,exe,ir,reference]:files[str(f)]=hashlib.sha256(f.read_bytes()).hexdigest()
  print(mode,name,'CLI/recoverable outcomes match',flush=True)
for f in [compiler,Path(__file__),suite]:files[str(f.resolve())]=hashlib.sha256(f.read_bytes()).hexdigest()
(out.parent/'cli-results.json').write_text(json.dumps(dict(records=rows,commands=commands,artifacts=files,script=Path(__file__).read_text()),indent=2)+'\n')
